# output that was captured from the original binary. If higher fidelity is
# required for more flags they can be added here.
try:
    with open('HELP_ORIG.txt','r',encoding='utf-8') as f:
        HELP_TEXT = f.read()
except Exception:
    # Fallback short help
    HELP_TEXT = "ripgrep (rg) recursively searches the current directory for lines matching a regex pattern. Use --help for more details."


def die(msg, code=2):
    sys.stderr.write(msg + '\n')
    sys.exit(code)


def read_patterns_from_file(fname):
    patterns = []
    try:
        with open(fname, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.rstrip('\n')
                patterns.append(line)
    except Exception as e:
        die(f"error: reading pattern file '{fname}': {e}")
    return patterns


def compile_patterns(pattern_strs):
    # compile list of regex patterns; empty patterns match everything
    compiled = []
    for p in pattern_strs:
        try:
            compiled.append(re.compile(p))
        except re.error as e:
            die(f"error: invalid regex '{p}': {e}")
    return compiled


def any_match(compiled, line):
    if not compiled:
        return False
    for rx in compiled:
        if rx.search(line):
            return True
    return False


def process_stream(stream, name, compiled, prefix):
    out = []
    for rawline in stream:
        # preserve original line endings
        line = rawline.rstrip('\n')
        if any_match(compiled, line):
            if prefix:
                out.append(f"{name}:{line}")
            else:
                out.append(line)
    return out


def main(argv):
    args = list(argv[1:])
    if not args:
        die('error: no pattern given', 2)

    # Handle --help and --version early
    if '--help' in args:
        sys.stdout.write(HELP_TEXT)
        sys.exit(0)
    if '--version' in args or '-V' in args:
        sys.stdout.write(VERSION_TEXT)
        sys.exit(0)

    patterns = []
    paths = []
    i = 0
    while i < len(args):
        a = args[i]
        if a == '-e':
            i += 1
            if i >= len(args):
                die('error: -e requires an argument')
            patterns.append(args[i])
        elif a == '-f':
            i += 1
            if i >= len(args):
                die('error: -f requires a file argument')
            patterns.extend(read_patterns_from_file(args[i]))
        elif a.startswith('-'):
            # skip unknown short options that take no args
            # For simplicity, ignore options we don't implement
            # but treat them as errors for unknown arg forms that look like flags
            # unless it's just '-' which means stdin
            if a == '-':
                paths.append('-')
            else:
                # unknown option; for simplicity, if it's -h map to help
                if a in ('-h','-?'):
                    sys.stdout.write(HELP_TEXT)
                    sys.exit(0)
                # ignore other options
                pass
        else:
            # first non-option token is the pattern unless patterns already provided
            if not patterns:
                patterns.append(a)
            else:
                paths.append(a)
        i += 1

    compiled = compile_patterns(patterns)

    outputs = []
    any_matches = False

    if not paths:
        # read stdin
        prefix = False
        try:
            lines = process_stream(sys.stdin, '', compiled, prefix=False)
            for l in lines:
                sys.stdout.write(l + '\n')
            any_matches = len(lines) > 0
        except Exception as e:
            die(f"error: reading stdin: {e}")
    else:
        prefix = len([p for p in paths if p != '-']) > 1
        for p in paths:
            if p == '-':
                lines = process_stream(sys.stdin, '', compiled, prefix=False)
                for l in lines:
                    sys.stdout.write(l + '\n')
                if lines:
                    any_matches = True
                continue
            if os.path.isdir(p):
                # very simple recursive traversal: skip directories for now
                continue
            try:
                with open(p, 'r', encoding='utf-8', errors='ignore') as f:
                    lines = process_stream(f, p, compiled, prefix)
                    for l in lines:
                        sys.stdout.write(l + '\n')
                    if lines:
                        any_matches = True
            except Exception as e:
                # ripgrep prints errors for failed opens; emulate minimally
                sys.stderr.write(f"error: failed to read '{p}': {e}\n")

    sys.exit(0 if any_matches else 1)

if __name__ == '__main__':
    main(sys.argv)
